int D[200005];
int del_time[200005];
int parent[200005], sz[200005], head[200005], tail[200005], left[200005], right[200005], nxt[200005], active[200005];
long long valS[200005], valT[200005];
int idxS[200005], idxT[200005];

int cmpS(const void *a, const void *b) {
    Point *p1 = (Point*)a;
    Point *p2 = (Point*)b;
    if (p1->val != p2->val) return (p1->val < p2->val) ? -1 : 1;
    return p1->idx - p2->idx;
}

int cmpT(const void *a, const void *b) {
    Point *p1 = (Point*)a;
    Point *p2 = (Point*)b;
    if (p1->val != p2->val) return (p1->val < p2->val) ? -1 : 1;
    return p1->idx - p2->idx;
}

