        int mid = (lo + hi) >> 1;
        if (valS[mid] <= s) lo = mid + 1;
        else hi = mid;
    }
    int end = lo - 1;
    int l = start, r = end + 1;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (idxS[mid] < L) l = mid + 1;
        else r = mid;
    }
    int left_pos = l;
    l = start, r = end + 1;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (idxS[mid] <= R) l = mid + 1;
        else r = mid;
    }
    int right_pos = l;
    return right_pos - left_pos;
}

int count_T(long long t, int L, int R) {
    if (L > R) return 0;
