    int l = start, r = end + 1;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (idxT[mid] < L) l = mid + 1;
        else r = mid;
    }
    int left_pos = l;
    l = start, r = end + 1;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (idxT[mid] <= R) l = mid + 1;
        else r = mid;
    }
    int right_pos = l;
    return right_pos - left_pos;
}

long long query(int i, int L, int R) {
    if (L > i) {
        int max_j = i + K;
        if (max_j > R) max_j = R;
        if (L > max_j) return 0;
        long long s_target = S[i] + K;
        long long t_target = T[i] - K;
        long long ans = count_S(s_target, L, max_j) + count_T(t_target, L, max_j);
        int j_overlap = i + K;
        if (j_overlap >= L && j_overlap <= max_j && A[j_overlap] == A[i]) ans--;
        return ans;
    } else if (R < i) {
        int min_j = i - K;
        if (min_j < L) min_j = L;
        if (R < min_j) return 0;
        long long s_target = S[i] - K;
        long long t_target = T[i] + K;
        long long ans = count_S(s_target, min_j, R) + count_T(t_target, min_j, R);
        int j_overlap = i - K;
        if (j_overlap >= min_j && j_overlap <= R && A[j_overlap] == A[i]) ans--;
        return ans;
    }
    return 0;
}

long long merge(int ra, int rb) {
    if (sz[ra] > sz[rb]) {
        int tmp = ra; ra = rb; rb = tmp;
    }
    int small = ra, large = rb;
    long long inc = 0;
    int L = left[large];
    int R = right[large];
    int i = head[small];
