    Point *ps = (Point*)malloc(N * sizeof(Point));
    Point *pt = (Point*)malloc(N * sizeof(Point));
    for (int i = 1; i <= N; i++) {
        ps[i-1].val = S[i];
        ps[i-1].idx = i;
        pt[i-1].val = T[i];
        pt[i-1].idx = i;
    }
    qsort(ps, N, sizeof(Point), cmpS);
    qsort(pt, N, sizeof(Point), cmpT);
    for (int i = 0; i < N; i++) {
        valS[i] = ps[i].val;
        idxS[i] = ps[i].idx;
        valT[i] = pt[i].val;
        idxT[i] = pt[i].idx;
    }
    free(ps);
    free(pt);

    // Initialize DSU
    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        sz[i] = 0;
        head[i] = tail[i] = i;
        left[i] = right[i] = i;
        nxt[i] = -1;
        active[i] = 0;
    }

    // Activate vertices that are present after all deletions
    for (int i = 1; i <= N; i++) {
        if (del_time[i] == 0) {
            active[i] = 1;
            sz[i] = 1;
        }
    }

    long long total = 0;
    long long *ans = (long long*)malloc((Q + 1) * sizeof(long long));

    // Initial merges to form components of present vertices
    for (int i = 1; i < N; i++) {
        if (active[i] && active[i+1]) {
            int ra = find(i);
            int rb = find(i+1);
            if (ra != rb) {
                total += merge(ra, rb);
            }
        }
    }
    ans[Q] = total;

    // Process deletions in reverse
    for (int t = Q; t >= 1; t--) {
        int x = D[t];
        active[x] = 1;
        sz[x] = 1;
        parent[x] = x;
        head[x] = tail[x] = x;
        left[x] = right[x] = x;
        nxt[x] = -1;

        if (x > 1 && active[x-1]) {
            int ra = find(x);
            int rb = find(x-1);
            if (ra != rb) total += merge(ra, rb);
        }
        if (x < N && active[x+1]) {
            int ra = find(x);
            int rb = find(x+1);
            if (ra != rb) total += merge(ra, rb);
        }
        ans[t-1] = total;
    }

    for (int t = 0; t <= Q; t++) {
        printf("%lld\n", ans[t]);
    }

    free(ans);
    return 0;
}
